-- Let me check the riskandmargin table schema more carefully
SELECT column_name, data_type FROM information_schema.columns WHERE table_name = 'riskandmargin' ORDER BY ordinal_position;

-- Also check if there's any other way to link these tables
SELECT column_name, data_type FROM information_schema.columns WHERE table_name = 'systemmonitoring' ORDER BY ordinal_position;

-- Maybe we should use riskandmargin directly with possum and get volmeter from marketstats 
-- without joining through orders at all

-- Let's check if there are 5 or more records in riskandmargin that have position data
SELECT COUNT(*) FROM riskandmargin WHERE risk_margin_profile ? 'position';

-- And see what the latest volmeter is
SELECT MAX(volmeter) as latest_volmeter FROM marketstats;
